INSERT INTO `faqs` VALUES (1,'emang ingyah?','<p>aefeawfa</p>','gataw',1,0,'2026-05-07 10:03:12','2026-05-08 09:20:45'),(2,'Bagaimana cara menentukan ukuran kacamata yang pas?','Anda bisa melihat angka yang tertera di gagang kacamata lama Anda (misal: 52-18-140) atau menggunakan fitur Virtual Try-On kami. Kami juga menyediakan panduan ukuran lengkap di setiap halaman produk.','Produk',1,1,'2026-05-08 09:17:57','2026-05-08 09:17:57'),(3,'Apakah bisa memesan kacamata dengan resep dokter (minus/silinder)?','Tentu saja! Anda cukup mengunggah foto resep dokter saat melakukan pemesanan atau mengisi data resep secara manual di form yang telah kami sediakan.','Lensa & Resep',2,1,'2026-05-08 09:17:57','2026-05-08 09:17:57'),(4,'Berapa lama proses pembuatan kacamata resep?','Proses pemasangan lensa resep standar membutuhkan waktu 1-3 hari kerja sebelum pesanan dikirimkan kepada Anda.','Pesanan',3,1,'2026-05-08 09:17:57','2026-05-08 09:17:57'),(5,'Apa itu lensa Blue Light/Anti Radiasi?','Lensa Blue Light dirancang khusus untuk menyaring sinar biru berbahaya dari layar gadget, sehingga mata Anda tidak cepat lelah dan membantu menjaga kualitas tidur.','Produk',4,1,'2026-05-08 09:17:57','2026-05-08 09:17:57'),(6,'Bagaimana jika kacamata yang saya terima tidak pas atau tidak sesuai?','Kami memberikan garansi 7 hari untuk penyesuaian atau pengembalian jika produk yang Anda terima mengalami cacat produksi atau tidak sesuai dengan pesanan Anda.','Layanan',5,1,'2026-05-08 09:17:57','2026-05-08 09:17:57'),(7,'Metode pembayaran apa saja yang tersedia?','Kami menerima pembayaran melalui Transfer Bank (Virtual Account), E-Wallet (OVO, Dana, ShopeePay), dan Kartu Kredit melalui payment gateway Xendit yang aman.','Pembayaran',6,1,'2026-05-08 09:17:57','2026-05-08 09:17:57');
/*!40000 ALTER TABLE `faqs` ENABLE KEYS */;
UNLOCK TABLES;

